        typ = str(it.get('type') or '')
        days = int(float(it.get('days_late') or 0))
        band = next((b for b in BANDS if b[0] <= days <= b[1]), BANDS[-1])
        deadline = add_business_days(today, band[2], hol)
        a1 = min(wk, deadline) if wk else deadline
        if typ == 'credit_card':
            name = 'credit card ending ' + str(it.get('card_last4') or '')
            floor = it.get('minimum_payment')
        elif typ == 'car_loan':
            name = 'car loan'
            floor = it.get('instalment_amount')
        else:
            name = 'personal loan'
            floor = it.get('instalment_amount')
        past = float(it.get('past_due') or 0)
        floor = float(floor or 0)
        pid = str(it.get('product_id') or '')
        facts.append(dict(product_id=pid, name=name, past_due=past, floor=floor, deadline=deadline.isoformat(), attempts=band[3], attempt1=a1.isoformat()))
        stmts.append('On your ' + name + ', ' + money(past) + ' is past due, ' + str(days) + ' days late.')
        lines.append('Product ' + str(n) + ': ' + name + ' (product_id ' + pid + '). Past due: ' + money(past) + '. Days late: ' + str(days) + ' (' + band[4] + ' band). Floor (lowest amount you may accept): ' + money(floor) + '. Deadline (latest date): ' + spoken_date(deadline) + ' = ' + deadline.isoformat() + '. Persuasion attempts allowed: ' + str(band[3]) + '. Attempt 1 date: ' + spoken_date(a1) + ' = ' + a1.isoformat() + '.')
        says.append('- Product ' + str(n) + ' attempt 1 (full amount): "Could you pay the full ' + money(past) + ' on your ' + name + ' by ' + spoken_date(a1) + '?"')
        says.append('- Product ' + str(n) + ' attempt 1 (if the full amount was too much): "Could you pay ' + money(floor) + ' on your ' + name + ' by ' + spoken_date(a1) + '? The rest stays overdue."')
        says.append('- Product ' + str(n) + ' floor offer when the full amount is too much (once): "I can record ' + money(floor) + ' on your ' + name + '. The rest stays overdue."')
        if band[3] >= 2:
            says.append('- Product ' + str(n) + ' attempt 2 (only after attempt 1 was refused): "Could you pay ' + money(floor) + ' on your ' + name + ' by ' + spoken_date(deadline) + '? The rest stays overdue."')
        else:
            says.append('- Product ' + str(n) + ': NO attempt 2. After attempt 1 is refused, stop for this product.')
        says.append('- Product ' + str(n) + ' date after the deadline: "The latest date I can record is ' + spoken_date(deadline) + '. Could you pay by then?"')
    table = []
    for i in range(0, 22):
        d = today + datetime.timedelta(days=i)
        bd = is_business_day(d, hol)
        tag = 'business day' if bd else ('HOLIDAY' if d in hol else 'weekend') + ', next business day ' + next_business_day(d, hol).isoformat()
        within = [str(k + 1) for k, f in enumerate(facts) if d.isoformat() <= f['deadline']]
        table.append(spoken_date(d) + ' = ' + d.isoformat() + ': ' + tag + ('; within deadline of product ' + ','.join(within) if within else '; after every deadline'))
    mon = week_monday(today)
    words = []
