import json
import re

WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('cannot read now: ' + s)

def parse_holidays(values):
    out = set()
    for v in values or []:
        try:
            out.add(datetime.date.fromisoformat(str(v)[:10]))
        except ValueError:
            pass
    return out

def is_business_day(d, holidays):
    return d.weekday() < 5 and d not in holidays

def next_business_day(d, holidays, include_today=False):
    if include_today and is_business_day(d, holidays):
        return d
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d, holidays):
        d = d + datetime.timedelta(days=1)
    return d

def add_business_days(d, n, holidays):
    for _ in range(int(n)):
        d = next_business_day(d, holidays)
    return d

def week_monday(d):
    return d - datetime.timedelta(days=d.weekday())

def last_business_day_of_week(d, holidays):
    day = week_monday(d) + datetime.timedelta(days=4)
    while day >= week_monday(d):
        if is_business_day(day, holidays):
            return day
        day = day - datetime.timedelta(days=1)
    return None

def spoken_date(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()

def money(amount):
    v = round(float(amount), 2)
    return '{:,.0f}'.format(v) if v == int(v) else '{:,.2f}'.format(v)

def as_list(value):
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return []
    if isinstance(value, dict):
        return [value]
    return value if isinstance(value, list) else []

def list_from_vars(vars, name, prefixes):
    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []
    if found:
        return found
    for prefix in prefixes:
        rows = dict()
        start = prefix + '.'
        for key, value in vars.items():
            if not str(key).startswith(start):
                continue
            rest = str(key)[len(start):]
            idx, _, field = rest.partition('.')
            if idx.isdigit():
                if field:
                    rows.setdefault(int(idx), dict())[field] = value
                else:
                    rows[int(idx)] = value
        if rows:
            return [rows[i] for i in sorted(rows)]
        whole = vars.get(prefix)
        if whole not in (None, ''):
            got = as_list(whole)
            if got:
                return got
    return []

BANDS = [(1, 7, 12, 1, 'early'), (8, 45, 7, 2, 'late')]
try:
    now = parse_now(vars.get('now'))
    hol = parse_holidays(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    today = now.date()
    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])
    wk = last_business_day_of_week(today, hol)
    if wk is None or wk <= today:
        wk = last_business_day_of_week(today + datetime.timedelta(days=7), hol)
    lines, says, facts, stmts = [], [], [], []
    for n, it in enumerate(items, 1):
        typ = str(it.get('type') or '')
        days = int(float(it.get('days_late') or 0))
        band = next((b for b in BANDS if b[0] <= days <= b[1]), BANDS[-1])
        deadline = add_business_days(today, band[2], hol)
        a1 = min(wk, deadline) if wk else deadline
        if typ == 'credit_card':
            name = 'credit card ending ' + str(it.get('card_last4') or '')
            floor = it.get('minimum_payment')
        elif typ == 'car_loan':
            name = 'car loan'
            floor = it.get('instalment_amount')
        else:
            name = 'personal loan'
            floor = it.get('instalment_amount')
        past = float(it.get('past_due') or 0)
        floor = float(floor or 0)
        pid = str(it.get('product_id') or '')
        facts.append(dict(product_id=pid, name=name, past_due=past, floor=floor, deadline=deadline.isoformat(), attempts=band[3], attempt1=a1.isoformat()))
        stmts.append('On your ' + name + ', ' + money(past) + ' is past due, ' + str(days) + ' days late.')
        lines.append('Product ' + str(n) + ': ' + name + ' (product_id ' + pid + '). Past due: ' + money(past) + '. Days late: ' + str(days) + ' (' + band[4] + ' band). Floor (lowest amount you may accept): ' + money(floor) + '. Deadline (latest date): ' + spoken_date(deadline) + ' = ' + deadline.isoformat() + '. Persuasion attempts allowed: ' + str(band[3]) + '. Attempt 1 date: ' + spoken_date(a1) + ' = ' + a1.isoformat() + '.')
        says.append('- Product ' + str(n) + ' attempt 1 (full amount): "Could you pay the full ' + money(past) + ' on your ' + name + ' by ' + spoken_date(a1) + '?"')
        says.append('- Product ' + str(n) + ' attempt 1 (if the full amount was too much): "Could you pay ' + money(floor) + ' on your ' + name + ' by ' + spoken_date(a1) + '? The rest stays overdue."')
        says.append('- Product ' + str(n) + ' floor offer when the full amount is too much (once): "I can record ' + money(floor) + ' on your ' + name + '. The rest stays overdue."')
        if band[3] >= 2:
            says.append('- Product ' + str(n) + ' attempt 2 (only after attempt 1 was refused): "Could you pay ' + money(floor) + ' on your ' + name + ' by ' + spoken_date(deadline) + '? The rest stays overdue."')
        else:
            says.append('- Product ' + str(n) + ': NO attempt 2. After attempt 1 is refused, stop for this product.')
        says.append('- Product ' + str(n) + ' date after the deadline: "The latest date I can record is ' + spoken_date(deadline) + '. Could you pay by then?"')
    table = []
    for i in range(0, 22):
        d = today + datetime.timedelta(days=i)
        bd = is_business_day(d, hol)
        tag = 'business day' if bd else ('HOLIDAY' if d in hol else 'weekend') + ', next business day ' + next_business_day(d, hol).isoformat()
        within = [str(k + 1) for k, f in enumerate(facts) if d.isoformat() <= f['deadline']]
        table.append(spoken_date(d) + ' = ' + d.isoformat() + ': ' + tag + ('; within deadline of product ' + ','.join(within) if within else '; after every deadline'))
    mon = week_monday(today)
    words = []
    for i, w in enumerate(WEEKDAYS):
        this_d = mon + datetime.timedelta(days=i)
        next_d = this_d + datetime.timedelta(days=7)
        words.append('"this ' + w + '" = ' + this_d.isoformat() + ', "next ' + w + '" = ' + next_d.isoformat())
    vars['statement_text'] = 'I am calling from the collections team about a late payment. ' + ' '.join(stmts)
    vars['facts_text'] = ('Today is ' + spoken_date(today) + ' = ' + today.isoformat() + '.\n' + '\n'.join(lines) +
        '\n\nSay these sentences exactly when they apply:\n' + '\n'.join(says) +
        '\n\nDate table (use it, never compute dates yourself):\n' + '\n'.join(table) +
        '\nWeekday words: ' + '; '.join(words) + '. A date before today is not allowed.')
    vars['facts_json'] = json.dumps(facts)
    vars['product_count'] = str(len(facts))
    vars['facts_state'] = 'ok' if facts else 'empty'
except Exception:
    vars['statement_text'] = 'I am calling from the collections team about a late payment.'
    vars['facts_text'] = 'The account details could not be read. Say you do not have that information.'
    vars['facts_json'] = '[]'
    vars['product_count'] = '0'
