"pre_process_code": "import datetime
import json
HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
try:
    vars['promise_block'] = ''
    b = config.get('body')
    if isinstance(b, dict):
        b['amount'] = round(float(str(b.get('amount')).replace(',', '')), 2)
        b['date'] = str(b.get('date') or '')[:10]
        facts = json.loads(vars.get('facts_json') or '[]')
        f = next((x for x in facts if str(x.get('product_id')) == str(b.get('product_id'))), None)
        today = str(vars.get('now') or '')[:10]
        msg = ''
        if f:
            d = datetime.date.fromisoformat(b['date'])
            if b['date'] < today:
                msg = 'The date is before today. Offer a business day from today on, not after ' + f['deadline'] + '.'
            elif b['date'] > f['deadline']:
                msg = 'The latest date you can record for this product is ' + f['deadline'] + '. Say so and offer that date.'
            elif d.weekday() >= 5 or b['date'] in HOL:
                n = d + datetime.timedelta(days=1)
                while n.weekday() >= 5 or n.isoformat() in HOL:
                    n = n + datetime.timedelta(days=1)
                nd = min(n.isoformat(), f['deadline'])
                msg = 'That is not a business day. Offer ' + nd + ' instead.'
            elif b['amount'] < float(f['floor']) - 0.001:
                msg = 'Below the floor of ' + str(f['floor']) + ': say it cannot be recorded and offer the floor once.'
            elif b['amount'] > float(f['past_due']) + 0.001:
                msg = 'More than the past-due amount ' + str(f['past_due']) + ': offer the past-due amount instead.'
        if msg:
            vars['promise_block'] = msg
            b.pop('product_id', None)
            b['date'] = ''
except Exception:
    pass
",
